update public.learning_paths
set
  title = 'U.S. Foreign Policy',
  goal = 'U.S. Foreign Policy',
  summary = 'This course examines how the United States defines interests, chooses strategies, builds institutions, deploys power, and responds to global change. Students study the historical development of U.S. foreign policy, the institutions and domestic forces that shape decisions, major regional and functional challenges, and the professional craft of policy analysis. The course combines historical cases, theory, current strategy documents, and applied memo writing so students can explain past choices and produce practical recommendations for contemporary problems.',
  data = $usfpjson${"slug": "u-s-foreign-policy", "title": "U.S. Foreign Policy", "description": "This course examines how the United States defines interests, chooses strategies, builds institutions, deploys power, and responds to global change. Students study the historical development of U.S. foreign policy, the institutions and domestic forces that shape decisions, major regional and functional challenges, and the professional craft of policy analysis. The course combines historical cases, theory, current strategy documents, and applied memo writing so students can explain past choices and produce practical recommendations for contemporary problems.", "topics": [{"id": "b87f7c07-5010-4c31-ab0c-02c375525d4d", "type": "topic", "title": "Foundations, Theories, and Grand Strategy", "description": "This opening unit gives students the analytical vocabulary to ask what U.S. foreign policy is trying to achieve, which theories explain its choices, and how leaders convert national interests into strategy.", "children": [{"id": "0e1ca6ce-4c74-4314-a0b3-49fa550d3447", "type": "subtopic", "title": "National interests, values, and strategic purpose", "children": [{"id": "2d84460d-d782-435f-9837-3451ca9b6532", "type": "concept", "title": "Security, prosperity, order, and liberty"}, {"id": "06b773c5-1c0e-4afa-81ac-1dbd914e4e24", "type": "concept", "title": "Exceptionalism, prudence, and restraint"}, {"id": "80e6ecf0-390a-446d-a6ae-5262b9f2b565", "type": "concept", "title": "Grand strategy as prioritization under scarcity"}], "description": "Students learn to distinguish vital interests from preferences and to see how values shape, constrain, and legitimize U.S. action."}, {"id": "b173ba5d-9e4c-4375-b9b9-f918b5372450", "type": "subtopic", "title": "IR theories for U.S. foreign policy", "children": [{"id": "e68035c2-9881-46b8-837a-f5c9c603371c", "type": "concept", "title": "Realism and balance of power"}, {"id": "b94c19b0-446d-43d4-b0c4-c390e9daf145", "type": "concept", "title": "Liberal institutionalism and interdependence"}, {"id": "451243f0-0d75-4777-9f1d-f35f7b71bfc9", "type": "concept", "title": "Constructivist and critical approaches"}], "description": "Theory gives students disciplined lenses for explaining why the United States chooses cooperation, coercion, retrenchment, or leadership."}, {"id": "4f2ac6b0-d83a-45c7-b017-444f1afd87c9", "type": "subtopic", "title": "Grand strategy debates", "children": [{"id": "ffa1d00f-7735-4678-bc7f-da1b7c323e0f", "type": "concept", "title": "Primacy and liberal internationalism"}, {"id": "ad4d9283-e2b0-4f76-bb44-af8f55ccd0de", "type": "concept", "title": "Offshore balancing and restraint"}, {"id": "12b2efd4-45b6-41be-a175-b08bf3594cd7", "type": "concept", "title": "Selective engagement and strategic competition"}], "description": "The unit frames major schools of strategic thought so students can compare policy prescriptions rather than memorize labels."}]}, {"id": "b2fa4c87-8b6a-4849-8743-f7b3a844700e", "type": "topic", "title": "Historical Foundations: Founding Era to World War II", "description": "History reveals the durable patterns beneath current policy: continental expansion, commercial diplomacy, hemispheric claims, contested intervention, and periodic shifts between restraint and international engagement.", "children": [{"id": "8b871d25-1e97-4b0f-af45-9a5d545cfe8c", "type": "subtopic", "title": "Founding principles and early diplomacy", "children": [{"id": "cf3ed84b-faab-4d77-9e27-1e39ffcfb339", "type": "concept", "title": "Washington's Farewell Address and neutrality"}, {"id": "406c9339-f021-45d2-9565-22d4075d36cf", "type": "concept", "title": "Jay Treaty and early trade diplomacy"}, {"id": "bf1b8857-546d-4d4f-9d1b-8d9e42b2ef57", "type": "concept", "title": "War powers and constitutional design"}], "description": "Students examine how sovereignty, neutrality, and commerce shaped the first foreign policy doctrines."}, {"id": "e5a57908-f654-4f30-9d5b-935efa5aa94b", "type": "subtopic", "title": "Expansion and hemispheric policy", "children": [{"id": "b0e67210-94af-4614-9565-22b68b85f2f5", "type": "concept", "title": "Manifest Destiny and continental strategy"}, {"id": "5587e616-2e94-4d12-b576-9a7812ce084c", "type": "concept", "title": "Monroe Doctrine and Roosevelt Corollary"}, {"id": "12586fb6-43a8-4727-a915-5d556dfa0ef1", "type": "concept", "title": "Intervention in the Caribbean and Latin America"}], "description": "This subtopic studies how territorial growth and the Monroe Doctrine built a regional order before global power arrived."}, {"id": "66f95b7a-16af-4289-bb4a-e492889c312c", "type": "subtopic", "title": "World wars and the end of isolation", "children": [{"id": "007b44a1-2a56-4943-8db5-cc6cc5236c38", "type": "concept", "title": "Wilson, collective security, and the League debate"}, {"id": "3d5d62a5-256f-4c7a-bd10-2116f207ec0d", "type": "concept", "title": "Interwar isolationism and neutrality laws"}, {"id": "0bc426c8-dd5d-427f-914e-5234a877fead", "type": "concept", "title": "World War II strategy and institution-building"}], "description": "Students trace how industrial capacity, alliance politics, and global war moved the United States into sustained international leadership."}]}, {"id": "12e80e84-dc8c-4964-b87e-0b29e4665426", "type": "topic", "title": "Cold War Strategy, Containment, and Nuclear Order", "description": "The Cold War remains the central laboratory for studying U.S. strategic planning, alliance management, nuclear deterrence, proxy conflict, covert action, and bureaucratic decision-making under existential risk.", "children": [{"id": "a23c8dbb-f5eb-4837-9a78-f028879cf5e5", "type": "subtopic", "title": "Containment and alliance architecture", "children": [{"id": "ae00bc3e-0388-4b77-8b26-8b9bf46e6c66", "type": "concept", "title": "Truman Doctrine and Marshall Plan"}, {"id": "ba9e0a4c-4f2b-4760-bea4-6d76cdcb0629", "type": "concept", "title": "NATO, Japan, Korea, and forward deployment"}, {"id": "13f88f96-7e1f-42c3-b31b-f65dc8e1252c", "type": "concept", "title": "Economic and ideological containment"}], "description": "Students learn how institutions translated geopolitical aims into enduring U.S. commitments."}, {"id": "c312ca98-ab48-4eb5-bc26-a60fcc909c50", "type": "subtopic", "title": "Nuclear deterrence and crisis management", "children": [{"id": "26dec756-25d5-41fe-aed0-5c11a4ee707f", "type": "concept", "title": "Massive retaliation and flexible response"}, {"id": "411aa7c1-8e1d-4064-88d0-94abae5dc6a8", "type": "concept", "title": "Cuban Missile Crisis and crisis bargaining"}, {"id": "a645ffa5-1aff-4024-a4d3-512fc2a17d7b", "type": "concept", "title": "Arms control, verification, and strategic stability"}], "description": "This subtopic develops fluency in deterrence theory and the risks of escalation during crises."}, {"id": "afa9a3ed-6d79-497f-9be3-12edaf826fe2", "type": "subtopic", "title": "Covert action, proxy wars, and legitimacy", "children": [{"id": "02b69595-d802-48d8-882f-64b63c57449b", "type": "concept", "title": "Iran, Guatemala, Chile, and covert intervention"}, {"id": "aa16a1e2-b154-4acd-941a-4c491b101de0", "type": "concept", "title": "Vietnam and limits of military power"}, {"id": "17680715-ee80-4a9e-b7e3-d62f6217eb1d", "type": "concept", "title": "Human rights, detente, and late Cold War change"}], "description": "Students evaluate the tools and costs of indirect competition in the developing world."}]}, {"id": "c17690e9-2300-487d-8b03-956c575f6446", "type": "topic", "title": "Post-Cold War Order and Liberal Internationalism", "description": "After 1991, U.S. policy makers faced the problem of how to use unmatched power: expand institutions, intervene selectively, promote democracy, manage globalization, and later defend a fraying order.", "children": [{"id": "ed437fdd-9d59-4238-81f4-4900de6ed2aa", "type": "subtopic", "title": "Unipolarity and enlargement", "children": [{"id": "2ae18041-c748-4bc4-bada-882791d20339", "type": "concept", "title": "NATO enlargement and European security"}, {"id": "1b614ad7-5f41-4951-ab9c-ea0bffdb1bcf", "type": "concept", "title": "Trade liberalization and globalization"}, {"id": "c8f76c40-3780-4fc3-96a7-88704f548cb2", "type": "concept", "title": "Democracy promotion and market reform"}], "description": "Students study how policymakers defined U.S. leadership when no peer competitor remained."}, {"id": "e5ddca4e-b5e9-4924-834f-b42cee3a5f47", "type": "subtopic", "title": "Humanitarian intervention and sovereignty", "children": [{"id": "e9bcaefa-a314-4ec4-93e5-40adf7721a5f", "type": "concept", "title": "Somalia, Rwanda, Bosnia, and Kosovo"}, {"id": "21dc5425-ca32-4656-bc47-6e180463e4d7", "type": "concept", "title": "Responsibility to Protect debates"}, {"id": "c158d361-734f-429a-a0a6-09dc2799c7fe", "type": "concept", "title": "Legitimacy, UN authorization, and coalition politics"}], "description": "This subtopic confronts the tension between nonintervention, human rights, and the use of force."}, {"id": "03d81102-2a9d-40e8-87ae-08ba43896265", "type": "subtopic", "title": "Backlash and order contestation", "children": [{"id": "c431cc0b-95cf-4a44-a150-79dd04457be0", "type": "concept", "title": "Russia, China, and status concerns"}, {"id": "a75c6119-0bf2-4a92-9613-8f1f2a1e3c33", "type": "concept", "title": "Globalization's domestic distributional effects"}, {"id": "871b0033-ab5f-4898-9c48-38f86dd59240", "type": "concept", "title": "Populism, sovereignty, and institutional distrust"}], "description": "Students analyze why U.S.-led order produced cooperation for some actors and resistance from others."}]}, {"id": "a9aa8864-70c3-4eca-bd45-6cc4272ecc87", "type": "topic", "title": "Actors and Institutions in U.S. Foreign Policy", "description": "Foreign policy is not made by a single actor. This unit maps the institutions, incentives, and constitutional conflicts that shape what the United States can decide and implement.", "children": [{"id": "91b08e66-096e-4e10-917a-439bb4824e1a", "type": "subtopic", "title": "Presidency, Congress, and the courts", "children": [{"id": "f7296773-27e6-4cea-be03-388745e84377", "type": "concept", "title": "Commander in chief and treaty powers"}, {"id": "63dddfbd-04cf-4e27-a865-7c82c91dbc80", "type": "concept", "title": "Appropriations, oversight, and sanctions legislation"}, {"id": "45054980-40f6-4065-bcb0-56b00c7ce0ee", "type": "concept", "title": "War Powers Resolution and judicial restraint"}], "description": "Students learn how formal authority, political incentives, and legal interpretation structure foreign policy power."}, {"id": "c65ec2fb-ffde-4611-9f3b-6ee5078d649a", "type": "subtopic", "title": "Bureaucracy and interagency process", "children": [{"id": "46665fb2-aaa1-4fb1-a381-66463680632a", "type": "concept", "title": "National Security Council process"}, {"id": "9753c60e-9e21-4c4e-a7d9-f07f75a1ef1e", "type": "concept", "title": "State, Defense, Treasury, Commerce, USAID, and DHS roles"}, {"id": "49614a90-171b-4dab-bd2f-c0f120696fe9", "type": "concept", "title": "Intelligence community estimates and policy support"}], "description": "This subtopic explains why implementation depends on organizational capacity, culture, and coordination."}, {"id": "a9afbe68-64ba-4785-b23d-f63346a2c1e8", "type": "subtopic", "title": "Domestic sources and political coalitions", "children": [{"id": "32bbf427-e067-4d6b-86e0-c885930028b2", "type": "concept", "title": "Public opinion and elite cueing"}, {"id": "cad7e664-7c3e-4dc1-a611-101e0a830745", "type": "concept", "title": "Lobbying, industry, and advocacy networks"}, {"id": "7ad01dbe-12de-4c59-a4aa-6b406f5fe2f8", "type": "concept", "title": "Federalism, governors, cities, and private actors"}], "description": "Students connect public opinion, parties, interest groups, media, and diaspora politics to policy outcomes."}]}, {"id": "278f6832-792e-4495-beef-6e6532c7010a", "type": "topic", "title": "Decision-Making, Intelligence, and Crisis Management", "description": "This unit turns from institutions to choice: how leaders perceive threats, process information, bargain internally, use intelligence, and make decisions when time is short and stakes are high.", "children": [{"id": "68f0ae7c-1a35-491a-95e3-96015b8639a0", "type": "subtopic", "title": "Decision-making models", "children": [{"id": "a79fc1e7-6b22-4b0e-adb1-bf84f7d8201a", "type": "concept", "title": "Allison's three models"}, {"id": "ecb3feba-20a6-4092-989d-47b79fba6d54", "type": "concept", "title": "Poliheuristic and prospect theory"}, {"id": "b459ceda-56ad-4548-947d-c55200eeb45b", "type": "concept", "title": "Groupthink, analogies, and motivated reasoning"}], "description": "Students compare rational actor, organizational process, bureaucratic politics, and psychological models of policy choice."}, {"id": "34d37e43-ac98-4108-9052-414af3eeff7e", "type": "subtopic", "title": "Intelligence and warning", "children": [{"id": "392c791e-5a31-4cf1-86bf-68086f8f1eb8", "type": "concept", "title": "Collection disciplines and analytic tradecraft"}, {"id": "0c799f80-2448-4d03-8ded-c57475e2455c", "type": "concept", "title": "Warning failure and surprise"}, {"id": "5a142ec7-7c4b-48e6-840a-77c26d56b921", "type": "concept", "title": "Intelligence oversight and covert action"}], "description": "This subtopic shows how uncertainty, collection limits, and politicization risks affect strategic judgment."}, {"id": "c566a33d-4d0d-453e-8b87-d8132ed7faca", "type": "subtopic", "title": "Crisis bargaining and escalation control", "children": [{"id": "6f7df2bb-c119-40ee-913d-c4cba04e4ee1", "type": "concept", "title": "Compellence and deterrence"}, {"id": "013f24fb-47e4-45ca-af79-468fa7768343", "type": "concept", "title": "Signaling, credibility, and audience costs"}, {"id": "36498201-5c05-4c08-8dd3-012fcbcfca4d", "type": "concept", "title": "Backchannels, hotlines, and de-escalation"}], "description": "Students practice identifying signals, red lines, off-ramps, and communication failures in high-pressure episodes."}]}, {"id": "84e2c2ef-129f-48de-ad58-6ec176cd6292", "type": "topic", "title": "Instruments of Statecraft", "description": "A foreign policy course must train students to match goals to tools. This unit compares the instruments available to policymakers and the tradeoffs that come with each.", "children": [{"id": "fc9624cc-2bf6-4fff-a1d9-b61c956575bc", "type": "subtopic", "title": "Diplomacy and negotiation", "children": [{"id": "fb65ae9d-a4c0-44cd-9765-3bf0eb05761b", "type": "concept", "title": "Bilateral and multilateral diplomacy"}, {"id": "913bb186-143e-4047-ad47-aba0635d209e", "type": "concept", "title": "Summits, mediation, and track-two channels"}, {"id": "e902bc8f-76c6-49a6-83d1-002665ee04dc", "type": "concept", "title": "Public diplomacy and strategic communication"}], "description": "Students learn diplomacy as a practical craft of representation, bargaining, coalition-building, and conflict management."}, {"id": "eff998ec-5a00-4f08-ae64-aa4691231d5e", "type": "subtopic", "title": "Military power and coercion", "children": [{"id": "bb8cd125-dd96-45fd-8c2d-0d24678a695a", "type": "concept", "title": "Force posture and alliance reassurance"}, {"id": "fbb11d67-2dbb-4d5b-852f-a75c7a728962", "type": "concept", "title": "Limited war, counterinsurgency, and security assistance"}, {"id": "6502bbb9-6b27-45b0-999d-bb536d99293d", "type": "concept", "title": "Civil-military relations and operational limits"}], "description": "This subtopic examines when force can deter, compel, reassure, punish, or fail."}, {"id": "0b286050-4223-47be-8a02-4ef0988c6d94", "type": "subtopic", "title": "Economic and technological statecraft", "children": [{"id": "1b35c08a-e73c-46f2-96c1-08d7993d6d16", "type": "concept", "title": "Sanctions design and evasion"}, {"id": "9cbda65f-8fa4-4154-b602-a34d91d525ca", "type": "concept", "title": "Trade, investment screening, and industrial policy"}, {"id": "876d59e1-e5dc-46bc-8545-a4e6b35939b6", "type": "concept", "title": "Foreign aid, development finance, and technology controls"}], "description": "Students evaluate the growing role of markets, finance, supply chains, data, and export controls in foreign policy."}]}, {"id": "16c60c3a-04f9-4577-b027-a16fa558463e", "type": "topic", "title": "International Law, Alliances, and Global Governance", "description": "This unit examines the rules and organizations through which U.S. power is constrained, amplified, legitimized, and contested, from NATO and the UN to trade and human-rights regimes.", "children": [{"id": "7f8611de-849c-4f43-b1e7-dc3b9878ab19", "type": "subtopic", "title": "International law and use of force", "children": [{"id": "8c294100-6c4c-4de3-a08b-a9b5734f0b35", "type": "concept", "title": "UN Charter Article 2(4) and Article 51"}, {"id": "2495b054-5515-4ade-9090-76dd918be1af", "type": "concept", "title": "Treaties, custom, and executive agreements"}, {"id": "9c96861c-312a-4224-b2c4-080a92961094", "type": "concept", "title": "International humanitarian and criminal law"}], "description": "Students understand the legal frameworks that shape intervention, self-defense, occupation, and accountability."}, {"id": "b58851f5-c980-44e5-b0bc-af5d6351cdba", "type": "subtopic", "title": "Alliances and security institutions", "children": [{"id": "36750452-2cdb-483d-8882-10d4bbe8576c", "type": "concept", "title": "NATO, Indo-Pacific alliances, and AUKUS-style arrangements"}, {"id": "1b2155d2-2592-4ecd-bf25-f935dd69b830", "type": "concept", "title": "Burden sharing and alliance politics"}, {"id": "d2a5289c-e602-4d46-8a1c-b524f815a03d", "type": "concept", "title": "Security guarantees and entrapment-abandonment risks"}], "description": "This subtopic explores how alliances distribute burdens, extend deterrence, and create credibility dilemmas."}, {"id": "7140e2ce-af95-4fbd-b316-69cfb5b733df", "type": "subtopic", "title": "Global governance and institutional legitimacy", "children": [{"id": "06dd029c-eb03-4712-ac8b-568ce3d09328", "type": "concept", "title": "UN system and Security Council politics"}, {"id": "5939ee1d-9d44-4c18-beb5-2b4d6b0163b2", "type": "concept", "title": "International financial institutions and regimes"}, {"id": "200864b9-0c30-4b74-93d2-b4fd6d6561f2", "type": "concept", "title": "Accountability, legitimacy, and informal governance"}], "description": "Students analyze cooperation on transnational problems and debates over reform of existing institutions."}]}, {"id": "bf027a5a-97ac-4048-9d4b-c0e22f99d8ad", "type": "topic", "title": "Regional Strategy and Area Analysis", "description": "Foreign policy happens in places. This unit trains students to combine area knowledge with strategic comparison so they can avoid one-size-fits-all policy prescriptions.", "children": [{"id": "501ff27a-2128-4490-be28-3f507dc73ef3", "type": "subtopic", "title": "Europe, Russia, and transatlantic security", "children": [{"id": "128ef00d-e07c-49f2-803b-58a20b5112ef", "type": "concept", "title": "Russia's war and deterrence posture"}, {"id": "1e98dd98-11cc-495c-84ef-a89da69c59bd", "type": "concept", "title": "NATO enlargement and burden sharing"}, {"id": "e4398589-f63f-4b59-9aca-b5c7dc3c8292", "type": "concept", "title": "Energy, reconstruction, and democratic resilience"}], "description": "Students assess NATO, Ukraine, sanctions, energy security, and the future of European order."}, {"id": "5a78ca7a-3aad-4b5e-9469-18e6aa516d66", "type": "subtopic", "title": "Indo-Pacific and China strategy", "children": [{"id": "8513e0b2-6c74-492a-9430-58b8b3e1d3f7", "type": "concept", "title": "Taiwan, South China Sea, and crisis stability"}, {"id": "cc994041-4dc2-4225-af8a-ff4cdc4ef1d7", "type": "concept", "title": "Japan, South Korea, Australia, India, and ASEAN"}, {"id": "11ce90c3-02a9-45b6-859b-c79d2d25ab55", "type": "concept", "title": "Technology, trade, and economic security"}], "description": "This subtopic studies the central arena of great-power competition and the challenge of deterrence without catastrophe."}, {"id": "37c07fcc-b7bf-4792-a64a-48f9305ed9d4", "type": "subtopic", "title": "Middle East, Africa, and the Americas", "children": [{"id": "6b7d8f55-a2f3-42c8-b837-4e97546ca3c1", "type": "concept", "title": "Iran, Israel-Palestine, Gulf politics, and counterterrorism"}, {"id": "9c476804-eb6d-4a93-82be-d225f2acdc85", "type": "concept", "title": "Latin America, migration, democracy, and narcotics"}, {"id": "1b271e4f-4ab3-46f6-bbd5-1e73b2f1cc28", "type": "concept", "title": "Africa policy, development, security partnerships, and great-power competition"}], "description": "Students compare regional policy problems where security, migration, development, democracy, and energy intersect."}]}, {"id": "5411ba1d-bfbb-4bf4-ab6a-ec1da298b29c", "type": "topic", "title": "Contemporary Security Challenges", "description": "This unit updates traditional security analysis for a landscape where military force, cyber operations, nuclear risk, terrorism, space systems, and irregular coercion interact.", "children": [{"id": "2c8a5d66-d67b-45c3-a9eb-7ed9b5a7b4ad", "type": "subtopic", "title": "Terrorism and counterterrorism", "children": [{"id": "c4c6dcd2-3662-4f4b-acc2-71b3591559b2", "type": "concept", "title": "Al-Qaeda, ISIS, and affiliated networks"}, {"id": "c1d18d68-8437-4cd4-bf51-6a7a49b08f74", "type": "concept", "title": "Homeland security and intelligence coordination"}, {"id": "2995061c-940b-4929-a296-fcb58de435ae", "type": "concept", "title": "Legal, ethical, and strategic limits of counterterrorism"}], "description": "Students assess the evolution from the War on Terror to persistent, networked, and regionally varied threats."}, {"id": "caf5abae-f987-49a3-a576-e445e69f798e", "type": "subtopic", "title": "Cyber, space, drones, and emerging technology", "children": [{"id": "6d50848f-3af1-4ba2-be4a-ce77491b21df", "type": "concept", "title": "Cyber deterrence and resilience"}, {"id": "b2bf0a22-cfbb-499a-8cdc-92e6988a5f7f", "type": "concept", "title": "Space security and satellite dependence"}, {"id": "ad725b5a-8375-4511-aff9-581fd54c59e0", "type": "concept", "title": "Autonomous systems, AI, and unmanned platforms"}], "description": "This subtopic explores new domains where attribution, escalation, and civilian infrastructure complicate policy."}, {"id": "159df5b0-467e-4ec8-804f-60ef06b23ecc", "type": "subtopic", "title": "Nuclear weapons and great-power competition", "children": [{"id": "c7cfa863-2bcd-4c15-8cee-3e965a03f406", "type": "concept", "title": "China, Russia, and strategic stability"}, {"id": "ae6f03bf-397a-4d74-a888-47aa2bc4f182", "type": "concept", "title": "Iran, North Korea, and nonproliferation"}, {"id": "0ed2a576-7b69-4588-97df-9673b4fcfece", "type": "concept", "title": "Arms control collapse and future verification"}], "description": "Students connect arms control, deterrence, proliferation, and conventional competition among major powers."}]}, {"id": "e8fbcb91-c497-4acf-83d1-16c86b1c3b12", "type": "topic", "title": "Political Economy, Climate, Technology, and Values", "description": "The line between domestic and foreign policy is increasingly thin. This unit treats economics, climate, technology, rights, and development as central elements of U.S. foreign policy, not add-ons.", "children": [{"id": "6b9acefa-beaa-4045-867f-dece86468532", "type": "subtopic", "title": "Trade, finance, and supply-chain security", "children": [{"id": "78362eb8-5ad7-4852-adf1-b888224efac9", "type": "concept", "title": "Trade agreements and economic coalitions"}, {"id": "db049dfa-0f14-4e44-8a11-bcc5e210d1b4", "type": "concept", "title": "Dollar power, financial sanctions, and debt"}, {"id": "9d4ba3a1-dbd8-436b-8faa-3bff3aed933c", "type": "concept", "title": "Critical minerals, chips, and supply-chain resilience"}], "description": "Students analyze the foreign policy consequences of interdependence, decoupling, sanctions, and industrial policy."}, {"id": "e6865fc1-1638-45f3-b998-c3c0bbdae50a", "type": "subtopic", "title": "Climate, energy, and development policy", "children": [{"id": "1e308a46-f859-4e36-b41b-07bd83b89b40", "type": "concept", "title": "Paris Agreement and climate diplomacy"}, {"id": "196e3480-bb8c-44ef-9d5c-ebfb5fc904ee", "type": "concept", "title": "Energy security and transition politics"}, {"id": "30693c1f-eebd-45bb-8b69-5a7fd74982cb", "type": "concept", "title": "Foreign assistance, USAID, and development finance"}], "description": "This subtopic frames climate and development as strategic issues involving diplomacy, finance, adaptation, and security."}, {"id": "7217de7f-3cbc-40e1-97d9-39dc4c0d991f", "type": "subtopic", "title": "Democracy, human rights, and migration", "children": [{"id": "7e0f8009-b196-4c3b-9c08-d4db4cb511d1", "type": "concept", "title": "Democracy support and anti-corruption"}, {"id": "1d5a36ee-4bb4-445f-a276-7e6586dfddc5", "type": "concept", "title": "Human rights law and humanitarian action"}, {"id": "ff725089-8340-4c0e-9057-45eb290aa9e9", "type": "concept", "title": "Refugees, migration, and border diplomacy"}], "description": "Students evaluate values-based policy when principles collide with security partnerships and domestic constraints."}]}, {"id": "58c5f0f7-575f-4720-a884-54ef6dc3a71e", "type": "topic", "title": "Policy Analysis, Memo Writing, and Strategic Recommendations", "description": "The capstone unit converts knowledge into professional work: students define policy problems, weigh options, communicate uncertainty, and defend recommendations before a decision-maker.", "children": [{"id": "a3db92e3-ccf0-48f3-838a-5d752366a011", "type": "subtopic", "title": "Problem definition and evidence", "children": [{"id": "b3567fdb-6ed2-4d7c-9239-17e1fa8d6a85", "type": "concept", "title": "Stakeholder and interest mapping"}, {"id": "bcbe7f34-528a-45bf-9950-9e935147d074", "type": "concept", "title": "Indicators, data quality, and source evaluation"}, {"id": "45a11ab8-f8f0-42b1-ae15-72b95241597f", "type": "concept", "title": "Counterfactuals and baseline scenarios"}], "description": "Students learn that good recommendations start with a precise problem, explicit assumptions, and credible evidence."}, {"id": "a010b402-aa72-4438-9d08-001f10aead79", "type": "subtopic", "title": "Options, criteria, and tradeoffs", "children": [{"id": "744aa42d-01ea-4539-b475-34f436896d84", "type": "concept", "title": "Effectiveness, feasibility, cost, risk, and ethics"}, {"id": "d214e768-21a8-470d-9e3b-cd22be1b81d2", "type": "concept", "title": "Second-order effects and unintended consequences"}, {"id": "157555a7-36f4-4a92-89f8-b96c16ad0f0b", "type": "concept", "title": "Implementation capacity and coalition constraints"}], "description": "This subtopic builds the core skill of comparing realistic alternatives against transparent criteria."}, {"id": "d0f36edf-a23c-4c7c-b8e1-10eaf91e3f88", "type": "subtopic", "title": "Memo, briefing, and scenario practice", "children": [{"id": "095692af-8bb8-4a0b-9020-e83a8004da76", "type": "concept", "title": "BLUF and executive-summary discipline"}, {"id": "d0d9eb96-4459-4537-bd2c-45e8f21817df", "type": "concept", "title": "Scenario planning and red-team review"}, {"id": "d935ea39-8316-4a59-9901-c34f824f2b5c", "type": "concept", "title": "Decision briefing, Q&A, and revision"}], "description": "Students practice the concise writing and oral briefing formats used in policy institutions."}]}], "dbBacked": true}$usfpjson$::jsonb,
